#include <stdio.h>

#define MAX(a,b) ((a) > (b) ? (a) : (b))

int main() {
    int n, m;
    scanf("%d,%d\n", &n, &m);

    char matrix[n][m];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            scanf("%c", &matrix[i][j]);
            getchar();
        }
    }

    int ans = 0;

    int offsets[4][2] = {{0, 1},
                         {1, 0},
                         {1, 1},
                         {1, -1}};

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (matrix[i][j] == 'M') {
                for (int k = 0; k < 4; k++) {
                    int offsetI = offsets[k][0];
                    int offsetJ = offsets[k][1];

                    int oldI = i - offsetI;
                    int oldJ = j - offsetJ;

                    if(oldI >= 0 && oldI < n && oldJ >= 0 && oldJ < m && matrix[oldI][oldJ] == 'M') {
                        continue;
                    }

                    int len = 1;
                    int newI = i + offsetI;
                    int newJ = j + offsetJ;

                    while (newI >= 0 && newI < n && newJ >= 0 && newJ < m && matrix[newI][newJ] == 'M') {
                        len++;
                        newI += offsetI;
                        newJ += offsetJ;
                    }

                    ans = MAX(ans, len);
                }
            }
        }
    }

    printf("%d\n", ans);

    return 0;
}
